import { useId, useLayoutEffect, useRef } from "react";

const FOCUSABLE_SELECTOR = [
  "a[href]",
  "button:not([disabled])",
  'input:not([disabled]):not([type="hidden"])',
  "select:not([disabled])",
  "textarea:not([disabled])",
  '[tabindex]:not([tabindex="-1"])',
].join(", ");

const bodyScrollLocks = new WeakMap();

function getFocusableElements(container) {
  return Array.from(container.querySelectorAll(FOCUSABLE_SELECTOR)).filter(
    (element) => {
      const tagName = element.tagName.toLowerCase();
      const isFormControl =
        tagName === "button" ||
        tagName === "input" ||
        tagName === "select" ||
        tagName === "textarea";

      if (isFormControl) {
        if (element.disabled || element.matches(":disabled")) {
          return false;
        }

        if (
          tagName === "input" &&
          String(element.type).toLowerCase() === "hidden"
        ) {
          return false;
        }
      }

      return true;
    },
  );
}

function acquireBodyScrollLock(body) {
  let state = bodyScrollLocks.get(body);

  if (!state) {
    state = {
      count: 0,
      previousOverflow: body.style.overflow,
    };
    bodyScrollLocks.set(body, state);
  }

  state.count += 1;
  body.style.overflow = "hidden";

  let released = false;

  return () => {
    if (released) return;
    released = true;

    if (bodyScrollLocks.get(body) !== state) return;

    state.count -= 1;

    if (state.count === 0) {
      body.style.overflow = state.previousOverflow;
      bodyScrollLocks.delete(body);
    } else {
      body.style.overflow = "hidden";
    }
  };
}

export function Dialog({ open, onClose, title, children }) {
  const titleId = useId();
  const dialogRef = useRef(null);
  const pressedOnBackdropRef = useRef(false);
  const isOpen = Boolean(open);

  useLayoutEffect(() => {
    if (!isOpen) return undefined;

    const dialog = dialogRef.current;
    if (!dialog) return undefined;

    const ownerDocument = dialog.ownerDocument;
    const previouslyFocused = ownerDocument.activeElement;
    const body = ownerDocument.body;
    const releaseScrollLock = body
      ? acquireBodyScrollLock(body)
      : () => {};

    pressedOnBackdropRef.current = false;

    const autofocusElement = dialog.querySelector("[data-autofocus]");
    const initialFocusElement =
      autofocusElement || getFocusableElements(dialog)[0] || dialog;

    if (typeof initialFocusElement.focus === "function") {
      initialFocusElement.focus();
    } else {
      dialog.focus();
    }

    return () => {
      pressedOnBackdropRef.current = false;
      releaseScrollLock();

      if (
        previouslyFocused &&
        previouslyFocused !== ownerDocument.body &&
        ownerDocument.contains(previouslyFocused) &&
        typeof previouslyFocused.focus === "function"
      ) {
        previouslyFocused.focus();
      }
    };
  }, [isOpen]);

  function handleKeyDown(event) {
    if (event.key === "Escape") {
      onClose();
      return;
    }

    if (event.key !== "Tab") return;

    const dialog = dialogRef.current;
    if (!dialog) return;

    const focusableElements = getFocusableElements(dialog);

    if (focusableElements.length === 0) {
      event.preventDefault();
      dialog.focus();
      return;
    }

    const firstFocusable = focusableElements[0];
    const lastFocusable = focusableElements[focusableElements.length - 1];
    const activeElement = dialog.ownerDocument.activeElement;

    if (activeElement === dialog) {
      event.preventDefault();
      (event.shiftKey ? lastFocusable : firstFocusable).focus();
      return;
    }

    if (event.shiftKey && activeElement === firstFocusable) {
      event.preventDefault();
      lastFocusable.focus();
    } else if (!event.shiftKey && activeElement === lastFocusable) {
      event.preventDefault();
      firstFocusable.focus();
    }
  }

  function handleBackdropMouseDown(event) {
    pressedOnBackdropRef.current = event.target === event.currentTarget;
  }

  function handleBackdropClick(event) {
    const shouldClose =
      pressedOnBackdropRef.current && event.target === event.currentTarget;

    pressedOnBackdropRef.current = false;

    if (shouldClose) {
      onClose();
    }
  }

  if (!isOpen) return null;

  return (
    <div
      data-testid="backdrop"
      onMouseDownCapture={handleBackdropMouseDown}
      onClickCapture={handleBackdropClick}
    >
      <div
        ref={dialogRef}
        role="dialog"
        aria-modal="true"
        aria-labelledby={titleId}
        tabIndex={-1}
        onKeyDown={handleKeyDown}
      >
        <h2 id={titleId}>{title}</h2>
        {children}
      </div>
    </div>
  );
}
